codebase.file:

html {
  width: 100vw;
  height: 100vh;
  margin: 0%;
  padding: 0%;
}

body {
  margin: 0%;
  padding: 0%;
  width: 100vw;
  height: 100vh;
  background-color: black;
}

a {
  color: white;
  cursor: pointer;
}

button {
  cursor: pointer;
}

.menu-consist-small {
  z-index: 100;
  position: fixed;
}

.menu-open {
  display: none;
}

.menu-open-show {
  margin-right: 0%;
  top: 0;
  display: flex;
  position: sticky;
}

/* intro animation */

.consist-intro {
  position: fixed;
  margin: 0;
  padding: 0;
  width: 100vw;
  height: 100vh;
  animation: changing-index 34s;
  z-index: -1;
}

@keyframes changing-index {
  0% {
    z-index: 100;
  }

  100% {
    z-index: -100;
  }
}

.on-top {
  z-index: 100;
}

.under-top {
  z-index: -100;
}

.intro-container {
  overflow: hidden;
  text-transform: lowercase;
  width: 100vw;
  height: 100vh;
  margin: 0px auto;
  display: flex;
  justify-content: center;
  align-items: center;
  background: #ffffff;
  animation: slide-out-container 4s cubic-bezier(0.97, 0.01, 0.36, 0.99) 2.8s;
  animation-fill-mode: forwards;
}

.text-wrapper {
  color: black;
  position: absolute;
}

.text {
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-weight: lighter;
  font-size: 7vw;
}

.text-1,
.text-3,
.text-4,
.text-8,
.text-9,
.text-11 {
  color: rgba(0, 0, 0, 0);
  -webkit-text-stroke: 1px rgb(0, 0, 0);
}

@keyframes blink {
  0% {
    opacity: 0%;
  }
  1% {
    opacity: 100%;
  }
  99% {
    opacity: 100%;
  }
  100% {
    opacity: 0;
  }
}

.text-3 {
  animation: blink 0.8s linear 0.7s, blink 0.8s linear 2.2s;
  opacity: 0;
}

.text-4 {
  animation: blink 0.8s linear 0.6s, blink 0.8s linear 2.3s;
  opacity: 0;
}

.text-5 {
  animation: blink 0.8s linear 0.5s, blink 0.8s linear 2.4s;
  opacity: 0;
}

.text-6 {
  animation: blink 0.8s linear 0.4s, blink 0.8s linear 2.5s,
    slide-out 1s linear 3.2s;
  opacity: 0;
}

.text-7 {
  animation: blink 0.8s linear 0.5s, blink 0.8s linear 2.4s;
  opacity: 0;
}

.text-8 {
  animation: blink 0.8s linear 0.6s, blink 0.8s linear 2.3s;
  opacity: 0;
}

.text-9 {
  animation: blink 0.8s linear 0.7s, blink 0.8s linear 2.2s;
  opacity: 0;
}

@keyframes slide-out {
  0% {
    opacity: 0%;
  }
  1% {
    opacity: 100%;
  }

  19% {
    opacity: 100%;
  }
  20% {
    opacity: 0%;
  }

  39% {
    opacity: 0%;
  }
  40% {
    opacity: 100%;
  }

  59% {
    opacity: 100%;
  }
  60% {
    opacity: 0%;
  }

  79% {
    opacity: 0%;
  }
  80% {
    opacity: 100%;
  }

  100% {
    opacity: 100%;
  }
}

@keyframes slide-out-container {
  0% {
    height: 100vh;
  }

  40% {
    height: 100vh;
  }

  100% {
    height: 0%;
  }
}

/* intro animation end */

.wrapper {
  position: relative;
  width: 100vw;
  height: 100vh;
  margin: 0%;
  padding: 0%;
}

.first-page {
  overflow: hidden;
  padding: 0%;
  margin: 0%;
  width: 100vw;
  height: 100vh;
  background-image: url(https://manuarya1610.github.io/contact-glass-blk-v3.jpeg);
  position: relative;
  background-repeat: no-repeat;
  -webkit-background-size: cover;
  -moz-background-size: cover;
  -o-background-size: cover;
  background-size: cover;
}

/* This is the navbar */

.navbar {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  overflow: hidden;
  top: 0%;
  position: relative;
  width: 100%;
  text-transform: uppercase;
  line-height: 5rem;
}

.site-menu {
  display: flex;
  width: 30%;
  padding: 0;
  justify-content: right;
}

.logo {
  width: fit-content;
  margin-left: 3%;
  margin-bottom: 3%;
}

.menu-item {
  margin-right: 12%;
}

.site-menu .menu-item {
  text-decoration: none;
  color: white;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
}

.hover-link {
  margin: 0 auto;
  border: none;
  background: none;
  color: white;

  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 1.2rem;
  text-transform: uppercase;
  text-decoration: none;
  display: inline-block;
  position: relative;
  cursor: pointer;
}

.hover-link > span {
  overflow: hidden;
  display: block;
  position: relative;
  pointer-events: none;
}

.hover-link > span > span {
  display: inline-block;
}

.hover-link > span > span:nth-of-type(1) {
  transition: 0.4s ease all;
}

.hover-link > span > span:nth-of-type(2) {
  transition: 0.4s ease all;
  transition-delay: 0.07s;
}

.hover-link > span > span > span {
  content: attr(data-text);
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  transform: translateY(200%);
}

.hover-link:hover > span > span,
.hover-link:focus > span > span {
  transform: translateY(-200%);
}

/* manu-arya hover */

.hover-this {
  cursor: pointer;
  transition: all 0.4s ease;
}

span {
  display: inline-block;
  pointer-events: none;
  transition: transform 0.2s linear;
}

/* this is my portfolio */

.contain-content {
  display: flex;
  width: 100%;
  position: relative;
}

.content {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 0.75rem;
  color: white;
  text-transform: uppercase;
  margin-top: 2%;
  margin-left: 7%;
  transform: rotate(-90deg);
}

/* glow */

.hi1 {
  cursor: default;
  transition: 0.1s;
}

.hi1:hover {
  color: #fff;
  text-shadow: 0 0 20px #00ffc8, 0 0 30px #00ffc8, 0 0 60px #00ffc8,
    0 0 100px #00ffc8;
}

/* end */

/* This is the hero-section element */

.contain-box {
  justify-content: space-between;
  margin-top: -3.5%;
  display: flex;
  width: 100%;
  height: 70%;
  position: absolute;
  overflow: hidden;
}

#box {
  padding-top: 5%;
  padding-bottom: 10%;
  width: 100%;
  height: 70%;
  position: relative;
  left: 3%;
  overflow: hidden;
}

#box1,
#box2,
#box3,
#box4,
#box5,
#box6 {
  width: 750px;
  height: 150px;
  font-size: 10.5vw;
  position: relative;
  overflow: hidden;
  display: inline-block;
}

#box1 {
  transform: skewY(-15deg);
}

#box2 {
  transform: skewY(15deg);
  margin-left: -5px;
  position: absolute;
}

#box3 {
  margin-top: -50px;
  transform: skewY(-15deg);
}

#box4 {
  margin-top: -50px;
  transform: skewY(15deg);
  margin-left: -4px;
  position: absolute;
}

#box5 {
  margin-top: -50px;
  transform: skewY(-15deg);
}

#box6 {
  margin-top: -50px;
  transform: skewY(15deg);
  margin-left: -0px;
  position: absolute;
}

#text1,
#text2,
#text3,
#text4,
#text5,
#text6 {
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  width: 1200px;
  height: 400px;
  position: absolute;
  display: inline-block;
  color: white;
  transition: all 0.4s;
  overflow: hidden;
}

#text1,
#text3,
#text5 {
  left: 750px;
  animation: anim 1s forwards 0.1s;
}

#text2,
#text4,
#text6 {
  left: -750px;
  animation: anim2 1s forwards;
}

@keyframes anim {
  from {
    left: 1200px;
  }
  to {
    left: 0px;
  }
}

@keyframes anim2 {
  from {
    left: 1200px;
  }
  to {
    left: -750px;
  }
}

#text3,
#text4,
#text5,
#text6 {
  color: white;
  opacity: 0.18;
}

#text2 {
  color: black;
  -webkit-text-fill-color: rgba(55, 41, 41, 0);
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: rgb(255, 255, 255);
}

/* hero end */

/* footer first page*/

.footer-first-page {
  position: absolute;
  margin: 0;
  padding: 0;
  bottom: 0;
  width: 100%;
  display: flex;
  flex-direction: row;
  justify-content: space-between;

  padding-bottom: 1%;
}

/* end */

/* DNA */

.contain-dna {
  padding-right: 15%;
  justify-content: right;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  margin-right: 4%;
  display: flex;
  width: 15%;
}

#dna {
  justify-content: right;
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: right;
  align-items: center;
  position: relative;
  transform: rotate(-90deg);
}

.line {
  height: 2px;
  width: 30px;
  background: rgba(255, 255, 255, 0.334);
  margin-top: 50%;
  position: absolute;
  transform: translateX(-50%);
  animation: anime 1s ease infinite;
}

.line::before {
  content: "";
  height: 10px;
  width: 10px;
  background: rgba(81, 161, 52, 0.2);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-radius: 20%;
  position: absolute;
  left: 0%;
  margin-top: -4px;
}

.line::after {
  content: "";
  height: 10px;
  width: 10px;
  background: rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-radius: 200px;
  border-radius: 20%;
  position: absolute;
  left: 100%;
  margin-top: -4px;
}

.line1 {
  margin-top: 50px;
  animation-delay: 0s;
  animation-duration: 1s;
}

.line2 {
  margin-top: 80px;
  animation-delay: 0.2s;
  animation-duration: 1s;
}

.line3 {
  margin-top: 110px;
  animation-delay: 0.3s;
  animation-duration: 1s;
}

.line4 {
  margin-top: 140px;
  animation-delay: 0.4s;
  animation-duration: 1s;
}

.line5 {
  margin-top: 170px;
  animation-delay: 0.5s;
  animation-duration: 1s;
}

.line6 {
  margin-top: 200px;
  animation-delay: 0.6s;
  animation-duration: 1s;
}

.line7 {
  margin-top: 230px;
  animation-delay: 0.7s;
  animation-duration: 1s;
}

.line8 {
  margin-top: 260px;
  animation-delay: 0.8s;
  animation-duration: 1s;
}

@keyframes anime {
  0% {
    width: 30px;
  }
  50% {
    width: 0px;
  }
  100% {
    width: 30px;
  }
}

/* end */

/* This is for socials */

.first-social {
  margin-left: 3%;
  position: relative;
  display: flex;
  flex-direction: row;
}

.f-links span {
  text-decoration: none;
  color: white;
}

.first-social .f-links {
  list-style: none;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 1.2rem;
  color: white;
  margin-right: 23%;
  padding-bottom: 3%;
}

.f-links {
  display: inline-block;
  position: relative;
  color: #ffffff;
}

.f-links:after {
  content: "";
  position: absolute;
  width: 100%;
  transform: scaleX(0);
  height: 2px;
  bottom: 0;
  left: 0;
  background-color: #ffffff;
  transform-origin: bottom right;
  transition: transform 0.25s ease-out;
}

.f-links:hover:after {
  transform: scaleX(1);
  transform-origin: bottom left;
}

/* end */

/* white-space */

.white-space {
  display: flex;
  position: relative;
  width: 100vh;
  height: 20vh;
}

/* END */

/* About Section */

a {
  text-decoration: none;
}

.about-button {
  padding: 1%;
  margin-top: 4%;
  margin-left: 4%;
  font-family: "Monument Extended Bold", Arial, Helvetica, sans-serif;
  display: flex;
  border: 1px solid white;
  justify-content: center;
  align-items: center;
  color: white;
  background-color: transparent;
}

.about-button {
  border: 1px solid currentColor;
  border-radius: 1.2em;
  color: rgb(255, 255, 255);
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 1.4rem;
  overflow: hidden;
  position: relative;
  text-decoration: none;
  transition: 1s transform ease-in-out;
  will-change: transform;
  z-index: 0;
}

.about-button::after {
  background-color: rgba(48, 90, 48, 0.738);
  color: black;
  content: "";
  display: block;
  height: 100%;
  width: 100%;
  position: absolute;
  left: 0;
  top: 0;
  transform: translate(-100%, 0) rotate(10deg);
  transform-origin: top left;
  transition: 0.2s transform ease-out;
  will-change: transform;
  z-index: -1;
}

.about-button:hover::after {
  transform: translate(0, 0);
}

@media (hover: hover) and (pointer: fine) {
  .about-button:hover {
    background-color: rgba(26, 61, 26, 0.738);
    transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
    border-color: transparent;
    color: black;
  }

  .about-button:hover::after {
    width: 100%;
    height: 100%;
  }
}

.about-about {
  width: 100vw;
}

.contain-about {
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: row;

  background-image: url(https://manuarya1610.github.io/ft546-v2.jpeg);
  background-size: cover;
  background-repeat: no-repeat;
  -webkit-background-size: cover;
  -moz-background-size: cover;
  -o-background-size: cover;
  background-size: cover;
  width: 100%;
  height: 100%;
}

.hello {
  margin-left: 3%;
}

.name {
  font-family: "Monument Extended Bold", Arial, Helvetica, sans-serif;
  font-size: 1.6rem;
  margin-top: 2.5%;
}

.about {
  position: relative;
  background-color: transparent;
  color: rgb(255, 255, 255);
  font-family: "montserratB", Arial, Helvetica, sans-serif;
  display: flex;
  flex-direction: row;
  justify-content: right;
}

#about-main {
  position: relative;
}

.about-box {
  width: 10.5%;
  display: inline-block;
  overflow: hidden;
}

.about-letter {
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 7rem;
  position: relative;
  left: -160px;
  transition: all 0.25s linear;
}

.about-wrapper {
  margin-left: 4%;
  width: 80vw;
  height: auto;
  display: flex;
  flex-direction: column;
}

.about-wrapper .about-line {
  width: 80%;
  position: relative;
  overflow: hidden;
}

.about-wrapper .about-line-1 {
  margin-bottom: 2%;
  font-family: Helvetica, sans-serif;
  font-size: 1.4rem;
  line-height: 1.5;
  width: 65%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

p {
  width: auto;
}

.about-wrapper .about-line .span-line {
  font-family: "Raleway", sans-serif;
  position: relative;
  font-size: 1.5rem;
}

.about-element {
  margin-top: -25%;
  color: white;
}

/* end */

/* This is the first 3d element */

.consist-element {
  position: sticky;
  background-color: transparent;
  color: #fff;
  min-height: 100%;
  display: grid;
  place-items: center;
  perspective: 500px;
  perspective-origin: 50% calc(50% - 150px);
}

.scene {
  position: relative;
  transform-style: preserve-3d;
}

.banner {
  display: flex;
  transform-style: preserve-3d;
  -webkit-animation: rotate 24s infinite linear;
  animation: rotate 24s infinite linear;
}

@-webkit-keyframes rotate {
  to {
    transform: rotateY(-360deg);
  }
}

@keyframes rotate {
  to {
    transform: rotateY(-360deg);
  }
}

.panel {
  position: absolute;
  transform: translate(-50%, -50%) rotateY(var(--angle)) translateZ(190px);
  width: 3.2rem;
  height: 160px;
  overflow: hidden;
}

.panel::before {
  position: absolute;
  left: var(--left);
  content: " Be the Exception! ";
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 5rem;
  width: -webkit-max-content;
  width: -moz-max-content;
  width: max-content;
  color: hsl(var(--hue), 85%, 85%);
}

.panel:nth-child(1) {
  --left: 0px;
  --hue: 0;
  --angle: 0deg;
}

.panel:nth-child(2) {
