.screen {
  position: absolute;
  width: 400px;
  height: 400px;
  transform: translate(-50%, -50%);
}

/* end */

/* This is the project part */

#project-about-main {
  position: relative;
  display: flex;
  justify-content: right;
}

#project-about-main-2 {
  margin-top: -3%;
  position: relative;
  display: flex;
  justify-content: right;
}

.project-about-box {
  width: 110px;
  height: 175px;
  display: inline-block;
  overflow: hidden;
}

.project-about-letter {
  color: white;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 7rem;
  font-weight: bold;
  position: relative;
  transition: all 0.25s linear;
}

/* PROJECTS PART */

.circular-text {
  position: absolute;
  top: 10%;
  left: 3%;
  transform: translate(-50%, -50%);
  color: rgb(0, 0, 0);
  font-size: 0.8rem;
  font-weight: bolder;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  transition: 0.5s ease-out;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.363);
}

.white-space-project {
  position: relative;
  height: 10vh;
}

.project-heading {
  margin-left: 2%;
  margin-top: 5%;
  font-family: "Monument Extended Regular", Arial, Helvetica, sans-serif;
  font-size: 2.5rem;
  color: white;

  color: black;
  -webkit-text-fill-color: rgba(
    55,
    41,
    41,
    0
  ); /* Will override color (regardless of order) */
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: rgb(255, 255, 255);
}

.project-container-main {
  overflow: hidden;
  padding: 0;
  margin: 0;
